import subprocess, re
W,Hh=10,14
def seqfor(dx,dy,w,h):
    txt = '\n'*dy + '\n'.join([' '*dx + '+' + '-'*(w-2) + '+'] + [' '*dx+'|'+' '*(w-2)+'|']*(h-2) + [' '*dx + '+' + '-'*(w-2) + '+'])+'\n'
    open('/tmp/shapes-agent/_t.txt','w').write(txt)
    subprocess.run(['/workspace/executable','/tmp/shapes-agent/_t.txt','/tmp/shapes-agent/_t.svg','--svg'],capture_output=True)
    s=open('/tmp/shapes-agent/_t.svg').read()
    d=[p for a,p in re.findall(r"<path ([^>]*?)d='([^']*)'", s) if 'white' in a][0]
    pts=[(int(float(a)),int(float(b))) for a,b in re.findall(r'([-\d.]+) ([-\d.]+)',d)]
    def cell(x,y): return ((x+2)*W+W//2, (y+2)*Hh+Hh//2)
    names={cell(dx,dy):'TL',cell(dx+w-1,dy):'TR',cell(dx,dy+h-1):'BL',cell(dx+w-1,dy+h-1):'BR'}
    return ''.join(names.get(p,'?') for p in pts)
for (w,h) in [(3,3),(4,3),(5,3),(6,3),(8,3),(3,4),(3,5),(10,3)]:
    row=[seqfor(dx,0,w,h) for dx in range(0,40)]
    # find period
    per=None
    for p in range(1,40):
        if all(row[i]==row[i+p] for i in range(0,40-p)): per=p; break
    print('w=%d h=%d cells=%d period=%s'%(w,h,2*w+2*(h-2),per))
    for i in range(0,40,10): print('   ',i,' '.join(x[:2] for x in row[i:i+10]))
EOF
